import 'data:text/javascript;base64,';
import { newMagicGame, newChallengeGame, addChallengeCard, reconcile, checkpoint, rollback, rollForFirst, beginTurn, draw, moveCard, userMulliganDraw, finishUserMulligan, assistantAutomaticMulligan, resolveStack, applyAssistantAction, IntegrityError } from 'data:text/javascript;base64,';
import { CHALLENGES, CHALLENGE_SOURCE_META } from 'data:text/javascript;base64,';


const SAVE_KEY='focused_magic_web_v0_2_state';
const LEGACY_SAVE_KEY='focused_magic_web_v0_1_state';
let state=null, aiBusy=false;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const status=(m)=>{$('#status').textContent=m;};


const cardCache = JSON.parse(localStorage.getItem('focused_magic_scryfall_cache')||'{}');
async function getCardInfo(name){
  const key=name.toLowerCase(); if(cardCache[key]) return cardCache[key];
  let r=await fetch('https://api.scryfall.com/cards/named?exact='+encodeURIComponent(name),{headers:{'Accept':'application/json'}});
  if(!r.ok) r=await fetch('https://api.scryfall.com/cards/named?fuzzy='+encodeURIComponent(name),{headers:{'Accept':'application/json'}});
  if(!r.ok) throw new Error(`Scryfall lookup failed for ${name}`);
  const d=await r.json(), faces=d.card_faces||[];
  const compact={name:d.name||name,mana_cost:d.mana_cost||'',type_line:d.type_line||'',oracle_text:d.oracle_text||'',power:d.power,toughness:d.toughness,loyalty:d.loyalty,image_uri:d.image_uris?.normal||faces[0]?.image_uris?.normal||'',card_faces:faces.map(f=>({name:f.name,mana_cost:f.mana_cost||'',type_line:f.type_line||'',oracle_text:f.oracle_text||'',power:f.power,toughness:f.toughness,image_uri:f.image_uris?.normal||''}))};
  cardCache[key]=compact; localStorage.setItem('focused_magic_scryfall_cache',JSON.stringify(cardCache)); return compact;
}
function formatRules(c){
  if(c.card_faces?.length) return c.card_faces.map(f=>`${f.name} ${f.mana_cost}\n${f.type_line}\n${f.oracle_text}${f.power!=null||f.toughness!=null?`\n${f.power||''}/${f.toughness||''}`:''}`.trim()).join('\n\n— — —\n\n');
  return `${c.name} ${c.mana_cost||''}\n${c.type_line||''}\n${c.oracle_text||''}${c.power!=null||c.toughness!=null?`\n${c.power||''}/${c.toughness||''}`:c.loyalty!=null?`\nLoyalty: ${c.loyalty}`:''}`.trim();
}
async function preview(name){ try{const c=await getCardInfo(name); $('#previewImg').src=c.image_uri||''; $('#previewRules').textContent=formatRules(c);}catch(e){$('#previewRules').textContent=`${name}\n${e.message}`;} }


function save(){ if(!state) return; reconcile(state); localStorage.setItem(SAVE_KEY,JSON.stringify(state)); status('Saved locally.'); }
function load(){ const raw=localStorage.getItem(SAVE_KEY)||localStorage.getItem(LEGACY_SAVE_KEY); if(!raw) throw new Error('No saved web game found.'); state=JSON.parse(raw); reconcile(state); render(); status('Saved game loaded.'); }
function doAction(label,fn){ try{ if(!state) throw new IntegrityError('No active game.'); fn(); save(); render(); if(label) status(label);}catch(e){status(e.message); alert(e.message);} }
function newGame(){state=newMagicGame();save();render();status('Game created. Roll for first.');}




let selectedChallenge=CHALLENGES[0];
function challengeById(id){return CHALLENGES.find(c=>c.id===Number(id));}
function challengeLoaderLabel(c){
  if(c.loader_status==='SOURCE_DERIVED_VISUAL_STATE_READY') return 'Visual state loader ready';
  if(c.loader_status==='BLOCKED_FULL_60_POOL_UNRESOLVED') return 'Blocked: full 60-card pool unresolved';
  return 'Guided setup / validation pending';
}
function openChallengeBrowser(){
  $('#challengeModal').classList.add('open');
  renderChallengeList();
  renderChallengeDetail(selectedChallenge||CHALLENGES[0]);
}
function closeChallengeBrowser(){$('#challengeModal').classList.remove('open');}
function renderChallengeList(){
  const level=$('#challengeLevelFilter').value;
  const box=$('#challengeList'); box.innerHTML='';
  CHALLENGES.filter(c=>level==='all'||String(c.level)===level).forEach(c=>{
    const b=document.createElement('button'); b.className='challenge-item'+(selectedChallenge?.id===c.id?' active':'');
    b.innerHTML=`<b>${c.number}. ${c.title}</b><br><span class="sub">${c.lesson}</span>`;
    b.onclick=()=>{selectedChallenge=c;renderChallengeList();renderChallengeDetail(c)};box.appendChild(b);
  });
}
function renderChallengeDetail(c){
  if(!c)return; selectedChallenge=c;
  $('#challengeLevelBadge').textContent=`Level ${c.level} — ${c.level_name}`;
  $('#challengeLoaderBadge').textContent=challengeLoaderLabel(c);
  $('#challengeTitle').textContent=`${c.number}. ${c.title}`;
  $('#challengeLesson').textContent=c.lesson;
  $('#challengeSetup').textContent=c.setup;
  $('#challengeObjective').textContent=c.objective;
  $('#challengeSolution').textContent=c.solution;
  $('#challengeSolution').classList.add('hidden');
  $('#challengeAuthorityNote').textContent=`${CHALLENGE_SOURCE_META.sourceStatus}. Content owner: ${CHALLENGE_SOURCE_META.owner}. Full starter pool: ${CHALLENGE_SOURCE_META.fullStarterPoolStatus}.`;
  $('#challengeLoad').disabled=c.loader_status==='BLOCKED_FULL_60_POOL_UNRESOLVED';
}
function loadChallenge(c){
  if(!c)throw new IntegrityError('Select a challenge first.');
  if(c.loader_status==='BLOCKED_FULL_60_POOL_UNRESOLVED')throw new IntegrityError('This challenge requires the complete 60-card starter pool, which KOSEIRA has not locked in the current handoff.');
  state=newChallengeGame(c); save(); render(); closeChallengeBrowser();
  status(c.manifest?`Challenge ${c.number} visual state loaded.`:`Challenge ${c.number} loaded in guided-setup mode.`);
}
function resetCurrentChallenge(){
  if(state?.mode!=='challenge'||!state.challenge)throw new IntegrityError('No challenge is active.');
  const c=challengeById(state.challenge.id); if(!c)throw new IntegrityError('Challenge definition is unavailable.');
  state=newChallengeGame(c); save(); render(); status(`Challenge ${c.number} reset.`);
}
function showCurrentChallengeText(kind){
  if(state?.mode!=='challenge'||!state.challenge)throw new IntegrityError('No challenge is active.');
  const text=kind==='solution'?state.challenge.solution:state.challenge.setup;
  alert(`${kind==='solution'?'Solution':'Setup'} — Challenge ${state.challenge.number}\n\n${text}`);
}


function cardEl(card,owner,zone,hidden=false){
  const el=document.createElement('div'); el.className='card'+(state?.tapped_ids?.includes(card.id)?' tapped':'')+(hidden?' back':'');
  if(hidden){el.textContent='Hidden';return el;}
  el.dataset.cardId=card.id; el.dataset.owner=owner; el.dataset.zone=zone; el.draggable=owner==='User';
  const img=document.createElement('img'); img.alt=card.name; const label=document.createElement('div'); label.className='name'; label.textContent=card.name; el.append(img,label);
  getCardInfo(card.name).then(c=>{img.src=c.image_uri||'';}).catch(()=>{});
  el.addEventListener('mouseenter',()=>preview(card.name)); el.addEventListener('click',()=>{preview(card.name); if(owner==='User'&&zone==='battlefield') toggleTap(card.id);});
  if(owner==='User') el.addEventListener('dragstart',ev=>ev.dataTransfer.setData('text/plain',JSON.stringify({cardId:card.id,owner,zone})));
  return el;
}
function fill(id,cards,owner,zone,hidden=false){const box=$(id);box.innerHTML='';cards.forEach(c=>box.appendChild(cardEl(c,owner,zone,hidden)));}
function render(){
  if(!state) return;
  let ok=true,msg='OK';try{reconcile(state);}catch(e){ok=false;msg=e.message}
  $('#integrity').textContent=msg;$('#integrity').className='integrity '+(ok?'ok':'bad');
  $('#active').value=state.active_player; if([...$('#phase').options].some(o=>o.value===state.phase)) $('#phase').value=state.phase; $('#priority').value=state.priority;$('#turn').textContent=state.turn;$('#rollResult').textContent=state.roll_for_first_result||'';
  const isChallenge=state.mode==='challenge'&&state.challenge;
  $('#challengeBanner').classList.toggle('hidden',!isChallenge); $('#challengeSetupTools').classList.toggle('hidden',!isChallenge);
  if(isChallenge){$('#challengeBannerTitle').textContent=`Challenge ${state.challenge.number}: ${state.challenge.title}`;$('#challengeBannerObjective').textContent=state.challenge.objective;}
  $('#userDeckTitle').textContent=isChallenge?'You — Challenge Player':'You — The Nothing';
  $('#aiDeckTitle').textContent=isChallenge?'Challenge Opponent':'Remalia — Dimir Tempo';
  $('#aiBattlefieldTitle').textContent=isChallenge?'Challenge Opponent — Battlefield':'Dimir Tempo — Battlefield';
  $('#userLife').textContent=state.user.life;$('#aiLife').textContent=state.assistant.life;$('#userLib').textContent=state.user.library.length;$('#aiLib').textContent=state.assistant.library.length;$('#userHandCount').textContent=state.user.hand.length;$('#aiHandCount').textContent=state.assistant.hand.length;
  fill('#userHand',state.user.hand,'User','hand');fill('#userBattlefield',state.user.battlefield,'User','battlefield');fill('#userGraveyard',state.user.graveyard,'User','graveyard');fill('#userExile',state.user.exile,'User','exile');
  fill('#aiBattlefield',state.assistant.battlefield,'Assistant','battlefield');fill('#aiGraveyard',state.assistant.graveyard,'Assistant','graveyard');fill('#aiExile',state.assistant.exile,'Assistant','exile');fill('#aiHand',state.assistant.hand,'Assistant','hand',true);
  const stack=$('#stack');stack.innerHTML='';state.assistant.stack.forEach(c=>stack.appendChild(cardEl(c,'Assistant','stack')));state.user.stack.forEach(c=>stack.appendChild(cardEl(c,'User','stack')));
  $('#log').textContent=state.log.slice(-200).join('\n');$('#log').scrollTop=$('#log').scrollHeight; $('#aiBtn').disabled=aiBusy||state.mode==='challenge';
}
function toggleTap(id){if(!state.tapped_ids)state.tapped_ids=[];const i=state.tapped_ids.indexOf(id);if(i>=0){state.tapped_ids.splice(i,1);state.log.push('User untaps a permanent.');}else{state.tapped_ids.push(id);state.log.push('User taps a permanent.');}save();render();}


$$('.zone').forEach(z=>{z.addEventListener('dragover',e=>{e.preventDefault();z.classList.add('drop')});z.addEventListener('dragleave',()=>z.classList.remove('drop'));z.addEventListener('drop',e=>{e.preventDefault();z.classList.remove('drop');try{const d=JSON.parse(e.dataTransfer.getData('text/plain'));let nz=z.dataset.zone;if(nz==='stack')nz='stack';if(!['hand','battlefield','graveyard','exile','stack'].includes(nz))return;doAction('Card moved.',()=>moveCard(state,d.owner,d.cardId,d.zone,nz));}catch(err){status(err.message)}})});


async function rulesForNames(names){const out={};for(const n of [...new Set(names)].sort()){try{out[n]=formatRules(await getCardInfo(n));}catch(e){out[n]=`Rules lookup unavailable: ${e.message}`;}}return out;}
async function assistantPrivateView(){
  const s=state; const names=[...s.assistant.hand,...s.assistant.battlefield,...s.assistant.graveyard,...s.assistant.exile,...s.assistant.stack,...s.user.battlefield,...s.user.graveyard,...s.user.exile,...s.user.stack].map(c=>c.name);
  return {game_id:'magic',card_rules:await rulesForNames(names),turn:s.turn,active_player:s.active_player,phase:s.phase,priority:s.priority,starting_player:s.starting_player,assistant:{life:s.assistant.life,hand:s.assistant.hand.map(c=>c.name),library_count:s.assistant.library.length,battlefield:s.assistant.battlefield.map(c=>c.name),graveyard:s.assistant.graveyard.map(c=>c.name),exile:s.assistant.exile.map(c=>c.name),stack:s.assistant.stack.map(c=>c.name),land_played:s.assistant.land_played,mulligans:s.assistant.mulligans},opponent_public:{life:s.user.life,hand_size:s.user.hand.length,library_count:s.user.library.length,battlefield:s.user.battlefield.map(c=>c.name),graveyard:s.user.graveyard.map(c=>c.name),exile:s.user.exile.map(c=>c.name),stack:s.user.stack.map(c=>c.name),land_played:s.user.land_played,mulligans:s.user.mulligans},recent_public_log:s.log.slice(-40)};
}
async function aiTakeAction(){
  if(!state||aiBusy)return;aiBusy=true;render();status('Remalia is thinking…');
  try{const view=await assistantPrivateView();const r=await fetch('/api/remalia',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({view})});const j=await r.json();if(!r.ok)throw new Error(j.error||`API error ${r.status}`);applyAssistantAction(state,j.action);save();render();status(`Remalia: ${j.action.action}`);}catch(e){status(`Remalia failed: ${e.message}`);alert(e.message);}finally{aiBusy=false;render();}
}
async function checkApi(){try{const r=await fetch('/api/remalia');const j=await r.json();status(j.configured?`Remalia server ready (${j.model}).`:'Remalia server exists, but OPENAI_API_KEY is not configured.');}catch(e){status('Remalia endpoint is not available in this local/static preview.');}}


$('#newBtn').onclick=()=>{q('constructedModal').classList.add('open');validateConstructedUI();constructedStatus('Page, Loose Leaf deck loaded. Saved Scryfall DB subset ready (57/57 identities).');};$('#rollBtn').onclick=()=>doAction('Roll completed.',()=>alert(rollForFirst(state)));$('#saveBtn').onclick=()=>{try{save()}catch(e){status(e.message)}};$('#loadBtn').onclick=()=>{try{load()}catch(e){status(e.message);alert(e.message)}};$('#checkpointBtn').onclick=()=>doAction('Checkpoint created.',()=>checkpoint(state,prompt('Checkpoint label:')||'Manual checkpoint'));$('#rollbackBtn').onclick=()=>{try{state=rollback(state);save();render();status('Rolled back.');}catch(e){status(e.message);alert(e.message)}};
$('#applyTurn').onclick=()=>doAction('Turn state applied.',()=>{state.active_player=$('#active').value;state.phase=$('#phase').value;state.priority=$('#priority').value;state.log.push(`Turn state: ${state.active_player}, ${state.phase}, priority ${state.priority}.`)});$('#userTurn').onclick=()=>doAction('User turn begun.',()=>beginTurn(state,'User'));$('#aiTurn').onclick=()=>doAction('Assistant turn begun.',()=>beginTurn(state,'Assistant'));
$('#userDraw').onclick=()=>doAction('You drew one card.',()=>{draw(state.user,1);state.log.push('User drew one card.');checkpoint(state,'After user draw')});$('#aiDraw').onclick=()=>doAction('Assistant drew one hidden card.',()=>{draw(state.assistant,1);state.log.push('Assistant drew one hidden card.');checkpoint(state,'After assistant draw')});$('#aiMulligan').onclick=()=>doAction('Assistant mulligan completed.',()=>assistantAutomaticMulligan(state));
$$('[data-life]').forEach(b=>b.onclick=()=>doAction('Life updated.',()=>{const p=b.dataset.life==='user'?state.user:state.assistant;const d=Number(b.dataset.delta);p.life+=d;state.log.push(`${p.name} life ${d>0?'gains':'loses'} ${Math.abs(d)} → ${p.life}.`)}));
$('#stackBf').onclick=()=>doAction('Stack resolved.',()=>resolveStack(state,'battlefield'));$('#stackGy').onclick=()=>doAction('Stack resolved.',()=>resolveStack(state,'graveyard'));$('#stackCounter').onclick=()=>doAction('Stack object countered.',()=>resolveStack(state,'graveyard',true));$('#recordAction').onclick=()=>doAction('Public action recorded.',()=>{const t=$('#manualAction').value.trim();if(!t)throw new IntegrityError('Enter a public action.');state.log.push(t);$('#manualAction').value='';checkpoint(state,'Public action recorded')});
$('#aiBtn').onclick=aiTakeAction;$('#apiBtn').onclick=checkApi;
$('#challengeBtn').onclick=openChallengeBrowser;$('#challengeClose').onclick=closeChallengeBrowser;$('#challengeLevelFilter').onchange=renderChallengeList;
$('#challengeLoad').onclick=()=>{try{loadChallenge(selectedChallenge)}catch(e){status(e.message);alert(e.message)}};
$('#challengeShowSolution').onclick=()=>$('#challengeSolution').classList.toggle('hidden');
$('#challengeSetupBtn').onclick=()=>{try{showCurrentChallengeText('setup')}catch(e){status(e.message)}};
$('#challengeSolutionBtn').onclick=()=>{try{showCurrentChallengeText('solution')}catch(e){status(e.message)}};
$('#challengeResetBtn').onclick=()=>{try{resetCurrentChallenge()}catch(e){status(e.message);alert(e.message)}};
$('#challengeAddCardBtn').onclick=()=>{try{if(state?.mode!=='challenge')throw new IntegrityError('Load a challenge first.');const name=$('#challengeAddCard').value.trim();addChallengeCard(state,$('#challengeAddOwner').value,$('#challengeAddZone').value,name);$('#challengeAddCard').value='';save();render();status(`Added ${name} to challenge state.`);}catch(e){status(e.message);alert(e.message)}};


$('#userMulligan').onclick=()=>{try{if(!state)throw new Error('No active game.');const n=userMulliganDraw(state);save();render();openMulligan(n);}catch(e){status(e.message);alert(e.message)}};
function openMulligan(needed){const modal=$('#mulliganModal'),box=$('#mulliganChoices');box.innerHTML='';$('#mulliganHelp').textContent=`Select exactly ${needed} card${needed===1?'':'s'} to put on the bottom.`;state.user.hand.forEach(c=>{const e=document.createElement('button');e.className='choose-card';e.dataset.id=c.id;e.textContent=c.name;e.onclick=()=>e.classList.toggle('selected');box.appendChild(e)});modal.classList.add('open')}
$('#mulliganFinish').onclick=()=>{try{const ids=$$('#mulliganChoices .selected').map(e=>e.dataset.id);finishUserMulligan(state,ids);$('#mulliganModal').classList.remove('open');save();render();status('London mulligan completed.');}catch(e){status(e.message);alert(e.message)}};


state=null;status('Page, Loose Leaf vs Dimir is the current match. Open Constructed vs AI to begin.');
// v0.6.6: launcher owns startup; do not auto-open Constructed on page load.
